/* Shared chapter restriction + selection feed every network/spatial projection. */
const NETWORKS={relations:['All relationships','Sourced relationship observations'],family:['Family','Kinship and marriage observations'],courtship:['Courtship','Love, proposals, engagements and refusals'],social:['Social ties','Friendship, hospitality and patronage'],conflict:['Conflict & obligation','Opposition, refusal and debt'],military:['Military & solidarity','Command, captivity and rescue'],information:['Information transfer','Directed disclosures; hearing does not imply belief'],mentions:['Co-occurrence','Names sharing a chapter; not necessarily meeting'],places:['People → places','Sourced physical-location observations']};
const RELATION_RULES=[
 ['social','hosts','is hosted by',false],['family','father of','son of',false],['family','father of','son of',false],['family','father of','daughter of',false],['family','brother of','sister of',false],['family','married to','married to',true],['military','aide-de-camp to','commander of',false],['family','father of','daughter of',false],['social','friend of','friend of',true],['family','mother of','son of',false],['social','promises patronage to','receives patronage promise from',false],['family','married to','married to',true],['family','daughter of','mother of',false],['family','father of','eldest son of',false],['family','father of','youngest son of',false],['family','uncle of','niece of',false],['social','childhood friend of','childhood friend of',true],['courtship','young lover of','young lover of',true],['family','married to','married to',true],['courtship','declines proposed match with','proposed match declined by',false],['conflict','duels with','duels with',true],['courtship','refuses proposal from','proposal refused by',false],['family','sister of','brother of',false],['conflict','owes gambling debt to','is owed gambling debt by',false],['courtship','dances with','dances with',true],['courtship','engaged to','engaged to',true],['social','plans elopement with','plans elopement with',true],['military','rescues and escorts','is rescued and escorted by',false],['courtship','reconciles with','reconciles with',true],['military','fellow prisoner of','fellow prisoner of',true],['military','rescues','is rescued by',false],['military','rescues','is rescued by',false],['family','married to','married to',true],['family','married to','married to',true]
];
const EDGE_COLORS={family:'#5b7757',courtship:'#a75f61',social:'#9b7947',conflict:'#ae543a',military:'#547b8a',information:'#78699a',mentions:'#9c9f8b',places:'#4f8c84'};
function observations(){return (L?.observations||[]).filter(o=>o.chapter<=state.horizon&&character(o.character)?.first<=state.horizon)}
function selectedObservations(){return observations().filter(o=>(!filters.character||o.character===filters.character)&&(!filters.place||o.place===filters.place)).sort((a,b)=>a.chapter-b.chapter||a.paragraph-b.paragraph)}
function semanticEdges(kind=filters.networkKind){
 let edges=[];
 if(kind==='information')edges=visibleKnowledge().filter(k=>k.recipient&&character(k.holder)?.first<=state.horizon&&character(k.recipient)?.first<=state.horizon).map(k=>({id:k.id,from:k.holder,to:k.recipient,label:k.mode==='letter'?'letter conveys':k.mode==='narrated'?'reported as telling':'tells',inverse:'receives claim from',type:'information',chapter:k.chapter,paragraph:k.paragraph,symmetric:false,claim:k.claim,note:k.note}));
 else if(kind==='places')edges=observations().map(o=>({id:o.id,from:o.character,to:'place:'+o.place,label:o.kind==='departed'?'departs from':o.kind==='arrived'?'arrives at':'observed at',inverse:'location of',type:'places',chapter:o.chapter,paragraph:o.paragraph,symmetric:false,note:o.note}));
 else if(kind==='mentions'){
  // Build chapter membership once, then accumulate each unordered pair.
  const chapters = new Map(), pairs = new Map();
  for (const c of unlockedChars()) for (const hit of mentions(c)) {
   if (!chapters.has(hit.chapter)) chapters.set(hit.chapter, []);
   chapters.get(hit.chapter).push({id:c.id, paragraph:hit.paragraphs[0]});
  }
  for (const [chapter, members] of [...chapters].sort((a,b)=>a[0]-b[0])) {
   for (let a=0;a<members.length;a++) for (let b=a+1;b<members.length;b++) {
    const from=members[a],to=members[b],id='co-'+from.id+'-'+to.id;
    if (pairs.has(id)) pairs.get(id).count++;
    else pairs.set(id,{id,from:from.id,to:to.id,count:1,chapter,paragraph:from.paragraph,
     inverse:'shared chapter mentions',type:'mentions',symmetric:true,
     note:'Name matches only. This does not establish a meeting or communication.'});
   }
  }
  edges=[...pairs.values()].map(e=>({...e,label:e.count+' shared chapters'}));
 }else edges=E.relations.map((r,i)=>{const [type,label,inverse,symmetric]=RELATION_RULES[i]||['social',r.label,r.label,true];return {...r,id:'r'+i,type,label,inverse,symmetric,note:r.label}}).filter(r=>r.chapter<=state.horizon&&character(r.from)?.first<=state.horizon&&character(r.to)?.first<=state.horizon&&(kind==='relations'||r.type===kind));
 return edges.filter(e=>(!filters.character||e.from===filters.character||e.to===filters.character)&&(!filters.place||kind!=='places'||e.to==='place:'+filters.place));
}
function entityName(id){return id.startsWith('place:')?placeName(id.slice(6)):name(id)}
function selectedName(){return character(filters.character)?.first<=state.horizon?name(filters.character):filters.character?'Selection not yet revealed':'Everyone revealed'}
function networkSlice(){
 const edges=semanticEdges();
 // Unfocused views retain revealed characters even without an edge in this layer.
 const ids=[...new Set([...(filters.character?[]:unlockedChars().map(c=>c.id)),...edges.flatMap(e=>[e.from,e.to])])];
 if(filters.character&&character(filters.character)?.first<=state.horizon&&!ids.includes(filters.character))ids.push(filters.character);
 ids.sort((a,b)=>a===filters.character?-1:b===filters.character?1:entityName(a).localeCompare(entityName(b)));
 return {edges,ids,nodes:ids,drawn:edges};
}
const networkLayoutCache = new Map();
function networkLayout(slice){
 const cacheKey=JSON.stringify([compactNetwork(),slice.nodes,slice.edges.map(e=>[e.from,e.to])]);
 if(networkLayoutCache.has(cacheKey))return networkLayoutCache.get(cacheKey);
 const mobile=compactNetwork(),ratio=mobile?0.86:1.7;
 const w=Math.max(mobile?380:960,Math.sqrt(slice.nodes.length)*175*Math.sqrt(ratio)),h=w/ratio;
 const pts=slice.nodes.map((id,i)=>{const a=i*2.399963,r=Math.sqrt((i+.5)/Math.max(1,slice.nodes.length));return {id,x:w/2+Math.cos(a)*r*w*.35,y:h/2+Math.sin(a)*r*h*.35}});
 const byId=new Map(pts.map((p,i)=>[p.id,{...p,index:i}]));
 pts.forEach((p,i)=>{p.index=i;byId.set(p.id,p)});
 // One deterministic layout for the complete graph; no nodes or edges are sampled.
 const pairs=[...new Map(slice.edges.map(e=>[[e.from,e.to].sort().join('|'),e])).values()];
 for(let step=0;step<180;step++){
  const forces=pts.map(p=>({x:(w/2-p.x)*.003,y:(h/2-p.y)*.003}));
  for(let i=0;i<pts.length;i++)for(let j=i+1;j<pts.length;j++){
   const dx=pts[i].x-pts[j].x,dy=pts[i].y-pts[j].y,d=Math.max(1,Math.hypot(dx,dy));
   const f=2400/(d*d)+Math.max(0,130-d)*.12;
   forces[i].x+=dx/d*f;forces[i].y+=dy/d*f;forces[j].x-=dx/d*f;forces[j].y-=dy/d*f;
  }
  for(const e of pairs){const a=byId.get(e.from),b=byId.get(e.to);if(!a||!b)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,f=(d-170)*.012/Math.max(1,Math.sqrt(pairs.length/Math.max(1,pts.length)));const i=a.index,j=b.index;forces[i].x+=dx/d*f;forces[i].y+=dy/d*f;forces[j].x-=dx/d*f;forces[j].y-=dy/d*f;}
  pts.forEach((p,i)=>{p.x=Math.max(90,Math.min(w-90,p.x+Math.max(-9,Math.min(9,forces[i].x))));p.y=Math.max(65,Math.min(h-75,p.y+Math.max(-9,Math.min(9,forces[i].y))));});
 }
 const result={w,h,pts};
 if(networkLayoutCache.size>=12)networkLayoutCache.delete(networkLayoutCache.keys().next().value);
 networkLayoutCache.set(cacheKey,result);
 return result;
}
function networkDrawing(slice){
 const mobile=compactNetwork(),{w,h,pts}=networkLayout(slice);
 const positions=new Map(pts.map(p=>[p.id,p]));
 const links=slice.drawn.map((e,i)=>{const a=positions.get(e.from),b=positions.get(e.to);const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,nx=-dy/len,ny=dx/len,offset=(i%3-1)*20,mx=(a.x+b.x)/2+nx*offset,my=(a.y+b.y)/2+ny*offset;const end={x:b.x-dx/len*25,y:b.y-dy/len*25},start={x:a.x+dx/len*25,y:a.y+dy/len*25};const d=`M${start.x},${start.y} Q${mx},${my} ${end.x},${end.y}`;return `<g tabindex="0" role="button" class="graph-edge" data-action="networkEdge" data-id="${e.id}" aria-label="${esc(entityName(e.from)+' '+e.label+' '+entityName(e.to))}"><path d="${d}" class="edge-hit" fill="none"/><path d="${d}" fill="none" stroke="${EDGE_COLORS[e.type]}" stroke-width="1.6" ${e.symmetric?'':`marker-end="url(#arrow-${e.type})"`}/>${slice.drawn.length<=(mobile?9:15)?`<text class="edge-label" x="${mx}" y="${my-6}" text-anchor="middle" fill="${EDGE_COLORS[e.type]}">${esc(e.label)}</text>`:''}</g>`}).join('');
 return `<svg id="networkCanvas" data-width="${w}" data-height="${h}" viewBox="0 0 ${w} ${h}" tabindex="0" role="group" aria-label="${esc(NETWORKS[filters.networkKind][0])} network; drag to pan, pinch to zoom"><defs>${Object.entries(EDGE_COLORS).map(([k,c])=>`<marker id="arrow-${k}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="${c}"/></marker>`).join('')}</defs>${links}${pts.map(p=>{const isPlace=p.id.startsWith('place:'),color=isPlace?'#4f8c84':EDGE_COLORS[filters.networkKind]||'#5b7757';return `<g class="graph-node" tabindex="0" role="button" aria-haspopup="dialog" aria-expanded="false" data-action="${isPlace?'networkPlace':'wiki-character'}" data-id="${isPlace?p.id.slice(6):p.id}" aria-label="${isPlace?'Inspect':'Wikipedia for'} ${esc(entityName(p.id))}"><circle class="node-hit" cx="${p.x}" cy="${p.y}" r="28" fill="transparent" stroke="none"/>${isPlace?`<rect x="${p.x-22}" y="${p.y-22}" width="44" height="44" rx="9" fill="#e6efea" stroke="${color}"/>`:`<circle cx="${p.x}" cy="${p.y}" r="23" fill="${p.id===filters.character?'#e0e8d6':'#faf9f0'}" stroke="${color}" stroke-width="${p.id===filters.character?2.5:1.3}"/>`}<text x="${p.x}" y="${p.y+5}" text-anchor="middle" font-size="14">${isPlace?'⌖':initials(name(p.id))}</text><text x="${p.x}" y="${p.y+41}" text-anchor="middle" font-size="13" class="node-name">${esc(entityName(p.id))}</text></g>`}).join('')}</svg>`;
}
function projectionBar(){return `<div class="projection-bar"><span>KEEP THIS SELECTION</span><button data-action="project" data-target="relations">Relationships</button><button data-action="project" data-target="information">Disclosures</button><button data-action="project" data-target="places">People → places</button><button data-action="project" data-target="atlas">Map & trails ↗</button><button data-action="project" data-target="query">Passages ↗</button></div>`}
function networkWorkspace(){const slice=networkSlice();return `<section class="network-workspace"><div class="workspace-heading"><div><span class="eyebrow">The novel as relations</span><h1>Networks</h1></div><span class="scope-badge">${esc(selectedName())}</span></div><div class="network-toolbar"><label>Network kind<select id="networkKind" aria-label="Network kind">${Object.entries(NETWORKS).map(([k,[n]])=>`<option value="${k}" ${filters.networkKind===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Focus on${charSelect()}</label>${filters.character?'<button class="compact" data-action="clearFocus">Clear focus</button>':''}<button class="textbutton" data-action="exportNetwork">Export view ↓</button></div><div class="network-canvas" id="networkViewport"><div class="network-tools" aria-label="Network controls"><button data-map="in" aria-label="Zoom in network">+</button><button data-map="out" aria-label="Zoom out network">−</button><button data-map="fit">Fit all</button><small>Drag to pan · pinch to zoom</small></div>${slice.nodes.length?networkDrawing(slice):empty('No supported edges for this network and chapter boundary. Slide forward or choose another kind.')}<div class="network-key">${[...new Set(slice.drawn.map(e=>e.type))].map(t=>`<span><i style="background:${EDGE_COLORS[t]}"></i>${esc(NETWORKS[t]?.[0]||t)}</span>`).join('')}<span>→ direction of the labeled relation</span></div></div><div class="network-status"><small>${slice.nodes.length} nodes · ${I.characters.length} indexed characters across the book · ${slice.edges.length} records · All shown · ${esc(NETWORKS[filters.networkKind][1])}</small></div>${projectionBar()}<details class="network-evidence"><summary>Articulated relationships & evidence (${slice.edges.length})</summary>${slice.edges.map(e=>`<div class="relationship-row"><span class="relationship-dot" style="background:${EDGE_COLORS[e.type]}"></span><div><strong>${esc(entityName(e.from))}</strong> <em>${esc(e.label)}</em> <strong>${esc(entityName(e.to))}</strong><small>${chLabel(e.chapter)} · ${e.symmetric?'symmetric relation':esc(entityName(e.to)+' '+e.inverse+' '+entityName(e.from))}</small></div><button class="textbutton" data-action="networkEdge" data-id="${e.id}">Inspect ↗</button></div>`).join('')}</details><p class="coverage">Edges record what is supported at their cited moment. They are not automatically assertions that a relationship still holds. Characters without a line have no sourced edge in this layer at this boundary. Tap a character to open Wikipedia in a dismissible window (full-story spoilers). Its chapter-safe dossier is available inside. More characters appear as you advance the chapter timeline.</p></section>`}
function universalTimeline(){const c=chapter(state.horizon);return `<header class="universal-timeline"><div class="timeline-top"><a href="#connections" data-view="connections" class="timeline-brand">War & Peace <span>ATLAS</span></a><button class="theme-toggle" data-action="theme" aria-label="Dark mode" aria-pressed="${typeof document!=='undefined'&&document.documentElement?.dataset.theme==='dark'}">☾ Dark mode</button><span id="horizonLabel">${chLabel(state.horizon)} <small>· ${state.horizon}/365</small></span></div><div class="chapter-rail" id="chapterRail" aria-label="Universal chapter timeline">${T.books.map(b=>`<div class="chapter-book"><span>${b.id<16?'BOOK '+b.id:'EPILOGUE '+(b.id-15)}</span><div>${T.chapters.filter(c=>c.book===b.id).map(c=>`<button class="chapter-tick ${c.id<=state.horizon?'revealed':''} ${c.id===state.horizon?'current':''}" data-action="timelineJump" data-chapter="${c.id}" ${c.id===state.horizon?'aria-current="step"':''} title="${chLabel(c.id)}" aria-label="Set horizon to ${chLabel(c.id)}">${c.chapter}</button>`).join('')}</div></div>`).join('')}</div><div class="scrubber-line"><button data-action="horizonPrev" aria-label="Previous chapter boundary" ${state.horizon===1?'disabled':''}>−</button><input type="range" min="1" max="365" value="${state.horizon}" id="chapterScrubber" aria-label="Chapters revealed through" aria-valuetext="${chLabel(state.horizon)}"><button data-action="horizonNext" aria-label="Next chapter boundary" ${state.horizon===365?'disabled':''}>+</button><details class="chapter-jump"><summary>Jump</summary><div><select id="horizonBook" aria-label="Reading boundary book">${T.books.map(b=>`<option value="${b.id}" ${b.id===c.book?'selected':''}>${b.id<16?'Book '+b.id:'Epilogue '+(b.id-15)}</option>`).join('')}</select><select id="horizonChapter" aria-label="Reading boundary chapter">${T.chapters.filter(x=>x.book===c.book).map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>Chapter ${x.roman}</option>`).join('')}</select><button data-action="applyBoundary">Set horizon</button></div></details></div><div class="timeline-foot"><span>${state.view==='atlas'?'Campaign: <strong>chapter opening</strong> · Scene pins: selected chapter':'Revealed through the <strong>end</strong> of the selected chapter'}</span><span>Slide to transform every view</span></div></header>`}
function workspaceRender(){closePeek();state.chapter=Math.min(state.chapter,state.horizon);$('#app').innerHTML=`${universalTimeline()}<div class="workspace-shell"><aside class="workspace-nav"><nav aria-label="Main navigation">${navs.map(([id,icon,title])=>`<button class="${state.view===id?'active':''}" data-view="${id}"><b>${icon}</b>${title}</button>`).join('')}</nav><form id="globalSearch"><input class="searchbox" name="search" aria-label="Search within reading horizon" placeholder="Search revealed text…"></form><button class="textbutton" data-action="about">Edition & methods ↗</button></aside><main class="workspace-main"><div class="content" id="mainContent">${views[state.view]()}<footer class="footer"><span>MAUDE · TEXT COMPLETE / ANNOTATION SELECTIVE</span><button class="textbutton" data-action="about">Sources & methods</button></footer></div></main></div>`;bind();bindWorkspace();save();history.replaceState(null,'',state.view==='read'?`#read-${state.chapter}-${focusParagraph??0}`:'#'+state.view);const rail=$('#chapterRail'),tick=rail.querySelector('.current');if(tick)rail.scrollLeft=Math.max(0,tick.offsetLeft-rail.clientWidth/2);if(focusParagraph!==null&&state.view==='read'){const p=focusParagraph;focusParagraph=null;setTimeout(()=>{$('#p'+p)?.classList.add('highlight');$('#p'+p)?.scrollIntoView({block:'center'})},30)}}
function applyHorizon(value,live=false){const n=Math.max(1,Math.min(365,Number(value)||1));state.horizon=n;state.chapter=Math.min(state.chapter,n);closePeek();if($('#drawer').children.length)closeDrawer();if(!live)return render();$('#horizonLabel').innerHTML=`${chLabel(n)} <small>· ${n}/365</small>`;$('#chapterScrubber').setAttribute('aria-valuetext',chLabel(n));$('#chapterRail').querySelectorAll('.chapter-tick').forEach(el=>{const id=+el.dataset.chapter;el.classList.toggle('revealed',id<=n);el.classList.toggle('current',id===n);if(id===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('#mainContent').innerHTML=views[state.view]();bind();bindWorkspace();save();}
function bindWorkspace(){bindAtlasMap($('#networkCanvas'),$('#networkViewport'));const slider=$('#chapterScrubber');if(slider){slider.oninput=e=>applyHorizon(e.target.value,true);slider.onchange=e=>{applyHorizon(e.target.value);$('#chapterScrubber').focus()}}const select=$('#networkKind');if(select)select.onchange=e=>{filters.networkKind=e.target.value;render()};const trail=$('#movementMode');if(trail)trail.onchange=e=>{filters.movementMode=e.target.value;render()};}
function latestLocations(obs){const last=new Map();for(const o of obs)last.set(o.character,o);return [...last.values()]}
function placeDossier(id){const obs=observations().filter(o=>o.place===id&&(!filters.character||o.character===filters.character));return `<span class="eyebrow">Physical-location evidence</span><h3 id="peek-title">${esc(placeName(id))}</h3>${obs.map(o=>`<div class="peek-record"><button class="textbutton" data-action="peekRelated" data-id="${o.character}">${esc(name(o.character))}</button><p>${esc(o.note)}</p>${peekCitation(o.chapter,o.paragraph)}</div>`).join('')||'<p>No revealed location observations for this selection.</p>'}`}
function openWorkspacePeek(anchor,html){closePeek();peek={anchor,pinned:true,html};anchor.setAttribute('aria-expanded','true');paintPeek(html)}
function movementMap(obs){
 const mapbox=filters.region==='central'?[10,46,21,52]:filters.region==='russia'?[23,49,43,62]:[-12,35,48,67],xy=(p)=>[(p.lon-mapbox[0])/(mapbox[2]-mapbox[0])*900,(mapbox[3]-p.lat)/(mapbox[3]-mapbox[1])*500];
 const places=I.places.filter(p=>p.kind!=='fictional'&&obs.some(o=>o.place===p.id));let routes='';
 if(filters.movementMode==='trail'){const by={};for(const o of obs)(by[o.character]??=[]).push(o);for(const [id,rows] of Object.entries(by))for(let i=1;i<rows.length;i++){const a=I.places.find(p=>p.id===rows[i-1].place),b=I.places.find(p=>p.id===rows[i].place);if(!a||!b||a.kind==='fictional'||b.kind==='fictional'||a.id===b.id)continue;const[x,y]=xy(a),[u,v]=xy(b);routes+=`<path d="M${x},${y} Q${(x+u)/2+20},${(y+v)/2-30} ${u},${v}" fill="none" stroke="#a66b4b" stroke-opacity=".5" stroke-width="1.5" stroke-dasharray="5 4"><title>${esc(name(id)+': '+a.name+' → '+b.name+'; recorded sequence, not an exact route')}</title></path>`}}
 return `<svg viewBox="0 0 900 500" role="group" aria-label="Sourced character locations and recorded journeys"><defs><clipPath id="moveClip"><rect width="900" height="500"/></clipPath></defs><rect width="900" height="500" fill="#e7ede6"/><g clip-path="url(#moveClip)">${G.map(f=>f.polygons.map(poly=>`<path class="geo" d="${poly.map((p,i)=>{const[x,y]=xy({lon:p[0],lat:p[1]});return(i?'L':'M')+x.toFixed(1)+','+y.toFixed(1)}).join('')}Z"/>`).join('')).join('')}${routes}${places.map(p=>{const[x,y]=xy(p),occupants=obs.filter(o=>o.place===p.id),ids=[...new Set(occupants.map(o=>o.character))];return `<g class="graph-node" data-action="networkPlace" data-id="${p.id}" tabindex="0" role="button" aria-label="Inspect ${esc(p.name)}"><circle class="node-hit" cx="${x}" cy="${y}" r="30" fill="transparent"/><circle cx="${x}" cy="${y}" r="${12+Math.min(ids.length,6)}" fill="#faf7e8" stroke="#8e6148" stroke-width="2"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12">${ids.length}</text><text x="${x+22}" y="${y-12}" class="map-place-label" font-size="13">${esc(p.name)}</text></g>`}).join('')}</g></svg>`;
}
function movementAtlas(){const obs=selectedObservations(),latest=latestLocations(obs),display=filters.movementMode==='trail'?obs:latest;const focused=filters.character;return `<div class="workspace-heading"><div><span class="eyebrow">Projection / people → places</span><h1>Whereabouts</h1></div><span class="scope-badge">${esc(selectedName())}</span></div><div class="network-toolbar"><label>Follow${charSelect()}</label><label>Location view<select id="movementMode"><option value="latest" ${filters.movementMode==='latest'?'selected':''}>Last recorded locations</option><option value="trail" ${filters.movementMode==='trail'?'selected':''}>Where they have been</option></select></label><label>Region<select data-filter="region"><option value="europe" ${filters.region==='europe'?'selected':''}>Europe</option><option value="central" ${filters.region==='central'?'selected':''}>Central Europe</option><option value="russia" ${filters.region==='russia'?'selected':''}>Russia</option></select></label></div><div class="movement-map svgpanel">${movementMap(display)}</div><div class="mapcaption">${filters.movementMode==='trail'?'Dashed lines connect recorded sightings in reading order; they are not reconstructed travel routes.':'Points show last recorded locations, not assumed continuous presence.'} Modern reference outlines; fictional estates appear in the records below, without invented coordinates.</div>${projectionBar()}<div class="where-grid">${latest.map(o=>`<button class="where-card" data-action="locationRecord" data-id="${o.id}"><span class="avatar ${character(o.character)?.family}">${initials(name(o.character))}</span><div><strong>${esc(name(o.character))}</strong><p>${esc(placeName(o.place))}</p><small>${o.chapter===state.horizon?'Recorded in this chapter':`Last recorded ${chLabel(o.chapter)}`} · ${o.kind}</small></div></button>`).join('')||empty('No physical-location observation is established for this selection at this boundary.')}</div><details class="network-evidence" ${focused?'open':''}><summary>Recorded journey · ${obs.length} observations</summary>${obs.map(o=>`<div class="journey-stop"><span class="journey-dot"></span><div><strong>${esc(name(o.character))} · ${esc(placeName(o.place))}</strong><small>${chLabel(o.chapter)} · ${o.kind}</small><p>${esc(o.note)}</p></div><button class="textbutton" data-action="locationRecord" data-id="${o.id}">Evidence ↗</button></div>`).join('')}</details><p class="coverage">A selective, sourced location ledger. Missing observations remain unknown; “last recorded” does not mean “still there.”</p>`}
function installWorkspace(){
 filters.networkKind='relations';filters.movementMode='latest';
 if(state.view==='overview'||!state.workspaceVersion)state.view='connections';state.workspaceVersion=3;
 navs.splice(0,navs.length,['connections','⌘','Networks'],['atlas','◎','Whereabouts'],['read','▤','Text'],['timeline','⌁','Events'],['knowledge','◇','Disclosures'],['characters','♙','People'],['query','⌕','Query'],['notebook','✎','Notes']);
 views.overview=networkWorkspace;views.connections=networkWorkspace;views.atlas=movementAtlas;render=workspaceRender;setHorizon=n=>applyHorizon(n);
 const oldAction=action;action=function(el){const a=el.dataset.action;
  if(a==='timelineJump')applyHorizon(+el.dataset.chapter);
  else if(a==='horizonPrev'||a==='horizonNext')applyHorizon(state.horizon+(a==='horizonNext'?1:-1));
  else if(a==='clearFocus'){filters.character='';filters.place='';render()}
  else if(a==='focusPerson'){filters.character=el.dataset.id;filters.place='';state.view='connections';closePeek();render()}
  else if(a==='project'||a==='projectPerson'){if(a==='projectPerson'){filters.character=el.dataset.id;filters.place='';}const target=el.dataset.target;if(['atlas','query'].includes(target))state.view=target;else{filters.networkKind=target;state.view='connections';}closePeek();render();}
  else if(a==='networkEdge'){const e=semanticEdges().find(e=>e.id===el.dataset.id);if(!e)return;openWorkspacePeek(el,`<span class="eyebrow">${esc(NETWORKS[e.type]?.[0]||e.type)} · sourced observation</span><h3 id="peek-title">${esc(entityName(e.from))}</h3><p class="predicate">${esc(e.label)}</p><h3>${esc(entityName(e.to))}</h3><p class="peek-meta">${esc(entityName(e.to)+' '+e.inverse+' '+entityName(e.from))}</p>${e.claim?`<p>${esc(e.claim)}</p>`:''}<p class="peek-meta">${esc(e.note||'')}</p>${peekCitation(e.chapter,e.paragraph)}<p class="peek-meta">Observed at this passage; continuing validity is not assumed.</p>`)}
  else if(a==='networkPlace')openWorkspacePeek(el,placeDossier(el.dataset.id));
  else if(a==='locationRecord'){const o=observations().find(o=>o.id===el.dataset.id);if(o)openWorkspacePeek(el,`<span class="eyebrow">Location observation · ${o.kind}</span><h3 id="peek-title">${esc(name(o.character))}</h3><p class="predicate">${esc(placeName(o.place))}</p><p>${esc(o.note)}</p>${peekCitation(o.chapter,o.paragraph)}<button class="compact" data-action="projectPerson" data-id="${o.character}" data-target="places">Project to location network</button>`)}
  else if(a==='exportNetwork')download('war-and-peace-network.json',{horizon:state.horizon,selection:{character:filters.character,place:filters.place},kind:filters.networkKind,edges:semanticEdges(),meaning:NETWORKS[filters.networkKind][1]});
  else oldAction(el);
 };
 const oldPeek=peekCharacterContent;peekCharacterContent=function(id){const html=oldPeek(id);return html?html+`<div class="peek-projections"><button class="compact" data-action="focusPerson" data-id="${id}">Focus network</button><button class="compact" data-action="projectPerson" data-id="${id}" data-target="atlas">Whereabouts ↗</button><button class="compact" data-action="projectPerson" data-id="${id}" data-target="information">Disclosures ↗</button></div>`:html};
}

